sqlite.source:
.bench_fixture("point_get/sqlite", sql.clone(), |s| {
            let mut stmt = s
                .conn
                .prepare_cached("SELECT COUNT(*) FROM docs WHERE id = ?1")
                .expect("sqlite prep");
            let n: i64 = stmt
                .query_row(rusqlite::params![s.probe_id], |r| r.get(0))
                .expect("sqlite get");
            black_box(n)
        })

